{
  "goal": "Analyze quarterly sales CSV files: detect quality issues, repair, revalidate, compute statistics, merge, review, and generate a consolidated Markdown report.",
  "steps": [
    {
      "name": "process_each_file",
      "kind": "foreach",
      "description": "Iterate over each input CSV file to perform per-file analysis, repair, and statistics.",
      "over": "inputs",
      "body": [
        {
          "name": "inspect_schema",
          "kind": "primitive",
          "capability": "csv.inspect_schema",
          "code": "{\"path\": \"${item}\"}",
          "output": {
            "name": "schema_report",
            "typeName": "Record",
            "fields": [
              { "name": "columns", "typeName": "List<Record>" },
              { "name": "row_count", "typeName": "Integer" },
              { "name": "issues", "typeName": "List<Record>" }
            ]
          }
        },
        {
          "name": "detect_issues",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\nimport json\n\ndf = pd.read_csv(${item})\nschema = ${schema_report}\n\nissues = {\n  'missing_values': df.isnull().sum().to_dict(),\n  'duplicates': df.duplicated().sum(),\n  'outliers': {}\n}\n\nenv['issues_report'] = issues",
          "inputBindings": [
            { "param": "schema_report", "source": "inspect_schema", "binding": "schema_report" }
          ],
          "output": {
            "name": "issues_report",
            "typeName": "Record",
            "fields": [
              { "name": "missing_values", "typeName": "Record" },
              { "name": "duplicates", "typeName": "Integer" },
              { "name": "outliers", "typeName": "Record" }
            ]
          }
        },
        {
          "name": "repair_file",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\nimport numpy as np\n\ndf = pd.read_csv(${item})\nissues = ${issues_report}\n\n# Repair missing values by filling with median for numeric columns\nfor col in df.select_dtypes(include=[np.number]).columns:\n    if issues['missing_values'].get(col, 0) > 0:\n        df[col].fillna(df[col].median(), inplace=True)\n\n# Drop duplicate rows\ndf.drop_duplicates(inplace=True)\n\nenv['repaired_data'] = df.to_dict(orient='records')",
          "inputBindings": [
            { "param": "issues_report", "source": "detect_issues", "binding": "issues_report" }
          ],
          "output": {
            "name": "repaired_data",
            "typeName": "List<Record>",
            "fields": []
          }
        },
        {
          "name": "revalidate_file",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\n\nrepaired = pd.DataFrame(${repaired_data})\n\n# Check for remaining issues\nrevalidation = {\n  'still_missing': repaired.isnull().sum().sum(),\n  'still_duplicates': repaired.duplicated().sum(),\n  'row_count': len(repaired),\n  'valid': True\n}\n\nenv['revalidation_report'] = revalidation",
          "inputBindings": [
            { "param": "repaired_data", "source": "repair_file", "binding": "repaired_data" }
          ],
          "output": {
            "name": "revalidation_report",
            "typeName": "Record",
            "fields": [
              { "name": "still_missing", "typeName": "Integer" },
              { "name": "still_duplicates", "typeName": "Integer" },
              { "name": "row_count", "typeName": "Integer" },
              { "name": "valid", "typeName": "Boolean" }
            ]
          }
        },
        {
          "name": "compute_stats",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\n\nrepaired = pd.DataFrame(${repaired_data})\n\nstats = {\n  'total_sales': repaired['sales'].sum() if 'sales' in repaired.columns else 0,\n  'average_sales': repaired['sales'].mean() if 'sales' in repaired.columns else 0,\n  'total_quantity': repaired['quantity'].sum() if 'quantity' in repaired.columns else 0,\n  'row_count': len(repaired)\n}\n\nenv['quarterly_stats'] = stats",
          "inputBindings": [
            { "param": "repaired_data", "source": "repair_file", "binding": "repaired_data" }
          ],
          "output": {
            "name": "quarterly_stats",
            "typeName": "Record",
            "fields": [
              { "name": "total_sales", "typeName": "Number" },
              { "name": "average_sales", "typeName": "Number" },
              { "name": "total_quantity", "typeName": "Integer" },
              { "name": "row_count", "typeName": "Integer" }
            ]
          }
        },
        {
          "name": "combine_file_results",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "result = {\n  'file_name': '${item}',\n  'schema': ${schema_report},\n  'issues': ${issues_report},\n  'revalidation': ${revalidation_report},\n  'stats': ${quarterly_stats}\n}\nenv['file_result'] = result",
          "inputBindings": [
            { "param": "schema_report", "source": "inspect_schema", "binding": "schema_report" },
            { "param": "issues_report", "source": "detect_issues", "binding": "issues_report" },
            { "param": "revalidation_report", "source": "revalidate_file", "binding": "revalidation_report" },
            { "param": "quarterly_stats", "source": "compute_stats", "binding": "quarterly_stats" }
          ],
          "output": {
            "name": "file_result",
            "typeName": "Record",
            "fields": [
              { "name": "file_name", "typeName": "String" },
              { "name": "schema", "typeName": "Record" },
              { "name": "issues", "typeName": "Record" },
              { "name": "revalidation", "typeName": "Record" },
              { "name": "stats", "typeName": "Record" }
            ]
          }
        }
      ],
      "output": {
        "name": "per_file_results",
        "typeName": "List<Record>",
        "fields": [
          { "name": "file_name", "typeName": "String" },
          { "name": "schema", "typeName": "Record" },
          { "name": "issues", "typeName": "Record" },
          { "name": "revalidation", "typeName": "Record" },
          { "name": "stats", "typeName": "Record" }
        ]
      }
    },
    {
      "name": "merge_results",
      "kind": "primitive",
      "capability": "execute_python",
      "code": "import pandas as pd\n\nresults = ${per_file_results}\n\n# Extract stats into a DataFrame\nstats_list = [r['stats'] for r in results]\nstats_df = pd.DataFrame(stats_list)\nstats_df['file'] = [r['file_name'] for r in results]\n\nmerged = {\n  'all_stats': stats_df.to_dict(orient='records'),\n  'total_sales': stats_df['total_sales'].sum(),\n  'average_sales': stats_df['average_sales'].mean(),\n  'total_quantity': stats_df['total_quantity'].sum()\n}\n\nenv['merged_data'] = merged",
      "inputBindings": [
        { "param": "per_file_results", "source": "process_each_file", "binding": "per_file_results" }
      ],
      "output": {
        "name": "merged_data",
        "typeName": "Record",
        "fields": [
          { "name": "all_stats", "typeName": "List<Record>" },
          { "name": "total_sales", "typeName": "Number" },
          { "name": "average_sales", "typeName": "Number" },
          { "name": "total_quantity", "typeName": "Integer" }
        ]
      }
    },
    {
      "name": "quality_review",
      "kind": "primitive",
      "capability": "execute_python",
      "code": "import pandas as pd\n\nmerged = ${merged_data}\nresults = ${per_file_results}\n\n# Aggregate issues from all files\nall_issues = []\nfor r in results:\n    all_issues.append({\n        'file': r['file_name'],\n        'missing_before': sum(r['issues']['missing_values'].values()),\n        'duplicates_before': r['issues']['duplicates'],\n        'missing_after': r['revalidation']['still_missing'],\n        'duplicates_after': r['revalidation']['still_duplicates'],\n        'valid': r['revalidation']['valid']\n    })\n\nreview = {\n  'overall_quality': 'PASS' if all(r['valid'] for r in results) else 'FAIL',\n  'file_reviews': all_issues,\n  'total_issues_before': sum(i['missing_before'] + i['duplicates_before'] for i in all_issues),\n  'total_issues_after': sum(i['missing_after'] + i['duplicates_after'] for i in all_issues)\n}\n\nenv['review_report'] = review",
      "inputBindings": [
        { "param": "merged_data", "source": "merge_results", "binding": "merged_data" },
        { "param": "per_file_results", "source": "process_each_file", "binding": "per_file_results" }
      ],
      "output": {
        "name": "review_report",
        "typeName": "Record",
        "fields": [
          { "name": "overall_quality", "typeName": "String" },
          { "name": "file_reviews", "typeName": "List<Record>" },
          { "name": "total_issues_before", "typeName": "Integer" },
          { "name": "total_issues_after", "typeName": "Integer" }
        ]
      }
    },
    {
      "name": "generate_report",
      "kind": "primitive",
      "capability": "execute_python",
      "code": "import json\n\nresults = ${per_file_results}\nmerged = ${merged_data}\nreview = ${review_report}\n\nreport_lines = []\nreport_lines.append('# Consolidated Sales Quality Report\\n')\nreport_lines.append('## Evidence Log\\n')\nreport_lines.append('| File | Schema Valid | Issues Before | Issues After | Valid |\\n')\nreport_lines.append('|------|--------------|---------------|--------------|-------|\\n')\nfor r in results:\n    issues_before = r['issues']['missing_values']|sum + r['issues']['duplicates']\n    issues_after = r['revalidation']['still_missing'] + r['revalidation']['still_duplicates']\n    report_lines.append(f\"| {r['file_name']} | {r['schema']['row_count']} rows | {issues_before} | {issues_after} | {r['revalidation']['valid']} |\\n\")\n\nreport_lines.append('\\n## Quarterly Statistics\\n')\nreport_lines.append(f\"- Total Sales: {merged['total_sales']}\\n\")\nreport_lines.append(f\"- Average Sales: {merged['average_sales']}\\n\")\nreport_lines.append(f\"- Total Quantity: {merged['total_quantity']}\\n\")\n\nreport_lines.append('\\n## Quality Review\\n')\nreport_lines.append(f\"- Overall Quality: {review['overall_quality']}\\n\")\nreport_lines.append(f\"- Total Issues Before: {review['total_issues_before']}\\n\")\nreport_lines.append(f\"- Total Issues After: {review['total_issues_after']}\\n\")\n\nreport = ''.join(report_lines)\nenv['final_report'] = report",
      "inputBindings": [
        { "param": "per_file_results", "source": "process_each_file", "binding": "per_file_results" },
        { "param": "merged_data", "source": "merge_results", "binding": "merged_data" },
        { "param": "review_report", "source": "quality_review", "binding": "review_report" }
      ],
      "output": {
        "name": "final_report",
        "typeName": "String",
        "fields": []
      }
    }
  ]
}
